package com.mo.economy_system.target.forge1201.network;
import com.mojang.logging.LogUtils;import com.mo.economy_system.common.market.MarketInvalidationFactory;import com.mo.economy_system.core.economy_system.market.MarketSavedData;import net.minecraft.server.level.ServerPlayer;import org.slf4j.Logger;
final class Forge1201MarketInvalidation{private static final Logger LOGGER=LogUtils.getLogger();static void broadcast(ServerPlayer source){var message=MarketInvalidationFactory.create(MarketSavedData.getInstance(source.serverLevel()).getView());for(ServerPlayer player:source.server.getPlayerList().getPlayers())try{Forge1201NetworkChannel.sendToPlayer(player,message);}catch(RuntimeException exception){LOGGER.error("Failed to invalidate market for player={}",player.getUUID(),exception);}}}
